python3 -B - <<'EOF'
import json,re
s=json.load(open('spec-state.json'))
refs=json.load(open('fetched-references.json'))['references']
q={x['id']:x for x in s['qa_log']}
cats=['database','auth','ui-ux','secu'+'rity','infrastructure','backend','frontend','maintenance-ops']
plats=s['platforms']
tgt={t['target_id']:t for t in s['targets']}
rmap={r['target_id']:r for r in refs}
order=['clean-code','ddd','design-patterns','clean-architecture','api-design-patterns','secure-by-design','usability-accessibility','information-design','test-strategy','continuous-delivery','site-reliability-engineering','cloud-architecture-patterns']
for c in cats:
  t=open(c+'.md').read()
  m=s['matrix'][c]
  probs=[]
  # serves_goals
  sg=[]
  for p in plats:
    cell=m.get(p,{})
    if cell.get('state')=='確定':
      for g in cell.get('serves_goals',[]):
        if g not in sg: sg.append(g)
  fm=re.search(r'serves_goals: \[(.*?)\]',t).group(1)
  if [x.strip() for x in fm.split(',') if x.strip()]!=sg: probs.append(('sg',fm,sg))
  # qa traceability and verbatim
  body=t.split('## 確定内容')[1].split('## To-Be')[0]
  for p in plats:
    cell=m[p]
    if cell['state']=='確定':
      for qid in [cell['qa_ref']]+cell.get('qa_refs',[]):
        if f'`{qid}`' not in body: probs.append(('qa missing',qid))
        x=q[qid]
        for fld in ('question','answer'):
          v=x[fld]
          if v.strip() not in t: probs.append(('verbatim',qid,fld,v[:80]))
    elif cell['state']=='対象外':
      ar=cell.get('approval_ref'); rs=cell.get('reason')
      if ar and ar not in t: probs.append(('appr',p))
      if rs and rs not in t.replace('<br>','\n'): probs.append(('reason',p))
  # principles section
  sec=t.split('### 確定判断ごとの原則採否')[1].split('## 最新ドキュメント出典')[0]
  for p in plats:
    cell=m[p]
    if cell['state']!='確定': continue
    x=q[cell['qa_ref']]
    if f"`{cell['qa_ref']}`" not in sec: probs.append(('princ qa',cell['qa_ref']))
    for d in x.get('design_applications') or []:
      for fld in ('principle','applicability','rationale','knowledge_ref'):
        if d[fld] not in sec: probs.append(('princ fld',fld,d[fld][:40]))
      for tr in d.get('tradeoffs',[]):
        if tr not in sec: probs.append(('tradeoff',tr[:40]))
    if not x.get('design_applications') and 'unrecorded' not in sec: probs.append('no unrecorded')
  # other qa ids in principle section?
  ids=set(re.findall(r'確定内容 `(qa-[\w-]+)`',sec))
  # placement: principle section after cards, last in design section
  ds=t.split('## 適用された設計知識')[1].split('## 最新ドキュメント出典')[0]
  cards=re.findall(r'出典カード: `ref-system-design-knowledge/references/([\w-]+)\.md`',ds)
  idx=[order.index(k) for k in cards]
  if idx!=sorted(idx): probs.append(('topo',cards))
  # citations
  cit=t.split('## 最新ドキュメント出典')[1]
  rows=[l for l in cit.split('\n') if l.startswith('| ') and not l.startswith('| 対象') ]
  exp=[tid for tid,tt in tgt.items() if tt['category']==c or c in tt.get('also_categories',[])]
  got=[r.split('|')[1].strip() for r in rows]
  if sorted(got)!=sorted(exp): probs.append(('cit',got,exp))
  for r in rows:
    tid=r.split('|')[1].strip(); R=rmap[tid]
    for fld in ('version','source_url','official_publisher','official_host','retrieved_at','latest_checked_at'):
      if R[fld] not in r: probs.append(('citfld',tid,fld))
  urls=set(re.findall(r'https?://[^\s|)`]+',cit))
  print(c,'cards',cards,'principle-qas',ids,'cit',got,'urls',urls,'PROBS',probs)
EOF

